			JW_VesselBoundCodeFindBox.Visible = transportMode == Core.Constants.TransportModes.Sea || transportMode == Core.Constants.TransportModes.InlandWaterwayTransport;
			JW_VesselBoundTextBox.Visible = transportMode == Core.Constants.TransportModes.Road || transportMode == Core.Constants.TransportModes.Rail;

