		void SetUpContextMenu()
		{
			MenuItem dividerMenuItem = new ZMenuItem("-");
			TransportsGrid.ContextMenu.MenuItems.Add(dividerMenuItem);

			MenuItem calculateDistanceMenuItem = new ZMenuItem(ResString.GetMultilingualString("3EB0F856-EC49-47e1-96EA-DE2265FAF452", "Calculate distance"));
			calculateDistanceMenuItem.Click += delegate
			{
				NotificationBuffer notifications = new NotificationBuffer();
				if (SelectedTransport != null)
				{
					SelectedTransport.SetCalculatedDistance(notifications);
					if (!string.IsNullOrEmpty(notifications.AsString))
					{
						Globals.Message.Show(notifications.AsString);
