			};

			MenuItem calculateDistanceForAllMenuItem = new ZMenuItem(ResString.GetMultilingualString("668294A4-E45E-42e0-9EE7-AF8B3579F157", "Calculate distance for all"));
			calculateDistanceForAllMenuItem.Click += delegate
			{
				var notifications = new NotificationBuffer();
				SetCalculatedDistanceForAll(notifications);
				if (!string.IsNullOrEmpty(notifications.AsString))
				{
					Globals.Message.Show(notifications.AsString);
				}
			};

			var validateFlightMenuItem = new ZMenuItem(ResString.GetMultilingualString("b26b52fb-de1f-4761-b9a9-aa38cd33f0d0", "Validate Flight against Global Flight Schedule"));
			validateFlightMenuItem.Click += delegate
			{
				if (SelectedTransport?.IsAir ?? false)
				{
					SelectedTransport.TryMatchAgainstOnlineFlights();
				}
				else
				{
					Globals.Message.ShowError(Res.GetString("63501b5a-4eb0-4a10-a21f-9eeeb7bb0908", "Please select an Air Routing Leg to validate."));
				}
			};

			TransportsGrid.ContextMenu.MenuItems.Add(calculateDistanceMenuItem);
			TransportsGrid.ContextMenu.MenuItems.Add(calculateDistanceForAllMenuItem);
			TransportsGrid.ContextMenu.MenuItems.Add(validateFlightMenuItem);
		}

		void SetCalculatedDistanceForAll(INotifications notifications)
		{
			foreach (var transport in AllTransports)
			{
				if (transport.JW_TransportMode == Constants.TransportModes.Road)
				{
					transport.SetCalculatedDistance(notifications);
				}
			}
		}

