		void GlobalSchedulesButton_Click(object sender, EventArgs e)
		{
			if (disableScheduleAndFlightButtonsWithMessage)
			{
				Globals.Message.ShowError(Res.GetString("FB2D6A50-AE3A-47AA-9E0B-BB46B2D1981B", "You can only import Global Flight Schedules via the parent"));
				return;
			}

			if (IsReadonlyTransportDueToPhaseSecurity)
			{
				Globals.Message.ShowError(ReadonlyTransportDueToPhaseSecurity);
				return;
			}

			var controller = ZControllerFactory.Create(ControllerIDs.RoutingLookups);
			controller.SetFormsModalTo(this.ParentForm);
			var form = (RealTimeRoutingForm)controller.ShowNewForm();
			if (form != null)
			{
				form.OpenedFromRoutingPlugin = true;
				form.FlightScheduleCreateFromJob = true;

				var transportCollectionForExtraLegs = RoutingCollection as ITransportCollection ?? TransportCollection;
				if (SelectedTransport == null && transportCollectionForExtraLegs != null)
				{
					SelectedTransport = transportCollectionForExtraLegs.AddNew() as Transport;
					SelectedTransport.JW_IsLinked = true;
				}

				if (SelectedTransport != null)
				{
					SetLastShownFormForTest(form);

					form.Filter.SetFilterDefaults(SelectedTransport.JW_RL_NKLoadPort, SelectedTransport.JW_RL_NKDiscPort, SelectedTransport.JW_ETD, SelectedTransport.JW_VoyageFlight.SubstringSafe(0, 2));
					form.FilterControl.FirePerformSearch();

					form.Closing += delegate
					{
						var realTimeRoute = form.ChosenRouting;
						if (realTimeRoute != null && form.DialogResult == DialogResult.OK && form.DepartureDate.IsValid)
						{
							var parentWithTransportCollectionInstance = SelectedTransport.Parent as ITransportParent;
							var transports = parentWithTransportCollectionInstance != null ? parentWithTransportCollectionInstance.Transports : TransportCollection;
							RealTimeRoutingUpdater.UpdateRouteFromChosenRealTimeRoute(SelectedTransport, transports, realTimeRoute, form.DepartureDate, form.IsImporting);
						}
					};
				}
			}
		}

		protected virtual void SetLastShownFormForTest(RealTimeRoutingForm form) { }

