		void ImportFromOnlineSchedulesButton_Click(object sender, EventArgs e)
		{
			ImportFromOnlineSchedules();
		}

		void ImportFromOnlineSchedules()
		{
			if (disableScheduleAndFlightButtonsWithMessage)
			{
				Globals.Message.ShowError(Res.GetString("6498CA6C-AE9E-4071-9C61-13AED8B05F9C", "You can only import Global Sailing Schedules via the parent"));
				return;
			}

			if (IsReadonlyTransportDueToPhaseSecurity)
			{
				Globals.Message.ShowError(ReadonlyTransportDueToPhaseSecurity);
				return;
			}

			var controller = ZControllerFactory.Create(ControllerIDs.OnlineSailingSchedules);
			controller.SetFormsModalTo(this.ParentForm);

			var onlineSchedulesForm = controller.ShowNewForm() as OnlineSchedulesForm;
			if (onlineSchedulesForm != null)
			{
				onlineSchedulesForm.AllowMultipleSelection = false;
				onlineSchedulesForm.SailingScheduleCreateFromJob = true;

				var filterDefaults = SelectedTransport == null
					? new OnlineSchedulesFilterStripBusinessObject.FilterDefaults()
					: new OnlineSchedulesFilterStripBusinessObject.FilterDefaults()
					{
						Origin = SelectedTransport.JW_RL_NKLoadPort,
						Destination = SelectedTransport.JW_RL_NKDiscPort,

						Departure = SelectedTransport.JW_ETD,
						Arrival = SelectedTransport.JW_ETA,

						Voyage = SelectedTransport.JW_VoyageFlight,
						Vessel = SelectedTransport.JW_Vessel,

						Carrier = SelectedTransport.Carrier != null
							? SelectedTransport.Carrier.OH_Code
							: ZString.Empty,
					};

				filterDefaults.IncludeRelatedPorts = ZBool.True;

				onlineSchedulesForm.SetFilterDefaults(filterDefaults);

				onlineSchedulesForm.SailingSchedulesImported += (_, eventArgs) =>
				{
					var importedRoute = eventArgs.ImportedRoutes.FirstOrDefault();

					if (importedRoute == null)
					{
						return;
					}

					var transportCollectionForExtraLegs = RoutingCollection as ITransportCollection ?? TransportCollection;
					importedRoute.MergeWithTransports(SelectedTransport, transportCollectionForExtraLegs);
				};
			}
		}

