		#region Route Visualizer

		async void ShowMapButton_Click(object sender, EventArgs e)
		{
			if (SelectedTransport == null)
			{
				Globals.Message.ShowError(Res.GetString("60ff5d31-0f62-4194-be1e-13774bd5ab2b", "You must select a Transport Leg to show the Vessel Movements Map."));
				return;
			}

			if (!await CheckMapTermsAcknowledged())
			{
				return;
			}

			var vesselMovementsUrlGenerator = ObjectFactory.Get<IVesselMovementsUrlGenerator>();
			using (var cts = new System.Threading.CancellationTokenSource(TimeSpan.FromSeconds(4)))
			{
				var tokenResult = await vesselMovementsUrlGenerator.GetTokenAsync(SelectedTransport.Parent.PK.ToString(), ct: cts.Token);
				if (!string.IsNullOrEmpty(tokenResult.ErrorMessage))
				{
					Globals.Message.ShowError(Res.GetString("f02cd022-21df-4562-901f-4a4960b43310", "Unable to show map: {0}", tokenResult.ErrorMessage));
					return;
				}
				if (tokenResult.RedirectUrl != null)
				{
					WebUrlLauncher.Launch(tokenResult.RedirectUrl.ToString());
					return;
				}

				var (mapUrl, mapValidationMessage) = vesselMovementsUrlGenerator.Generate(tokenResult.Token, SelectedTransport, VesselMovementsUrlGeneratorOptions.None);
				if (!string.IsNullOrEmpty(mapValidationMessage))
				{
					Globals.Message.ShowError(Res.GetString("f02cd022-21df-4562-901f-4a4960b43310", "Unable to show map: {0}", mapValidationMessage));
					return;
				}

				WebUrlLauncher.Launch(mapUrl.ToString());
			}
		}

		async Task<bool> CheckMapTermsAcknowledged()
		{
			if (FreightDataRegistry.Instance.EnableRouteVisualizerMyAccountLogin.Value)
			{
				var uacFormChecker = ObjectFactory.Get<ISystemUserAccountCollectionTermChecker>();
				if (!await uacFormChecker.CheckTermAcknowledged())
				{
					Globals.Message.ShowError(Res.GetString("5fb5b9a7-a826-44b9-8207-64cac4793c1c", "Unable to show map: My Account terms of use have not been accepted."));
					return false;
				}
			}

			return true;
		}

