		#region BookingConfirmationUpdateButton_Click

		void BookingConfirmationUpdateButton_Click(object sender, EventArgs e)
		{
			var provider = AirlineTrackingEventProvider;
			if (provider == null)
			{
				return;
			}

			if (BookingConfirmationGrid.SelectedElements.Length != 1)
			{
				Globals.Message.ShowError(ResString.GetMultilingualString("52dea2aa-0aeb-4739-9c57-e016bf14bc3a", "Please select an item from Booking Confirmation grid."));
				return;
			}

			var selectedBookingConfirmation = BookingConfirmationGrid.SelectedElements[0] as BookingConfirmation;
			var matched = provider.MatchAndUpdateRoutingLeg(selectedBookingConfirmation, () =>
			{
				var caption = ResString.GetMultilingualString("57138890-eb00-4f20-b0cb-02b89366ad74", "Update Routing Leg - Booking Confirmation");
				var dialogContext = new DialogDefaultContext(new ZGuid("e00ebf50-6134-4754-bbcf-4866d5eb9284"),
					caption,
					ZMessageBoxButtons.YesNo,
					ZMessageBoxIcon.Question,
					null,
					showCheckboxOnly: true);

				var confirmation = ResString.GetMultilingualString("0cfde9ba-99ae-44e5-9a0c-2e135d04bc72", "Are you sure you want to update/replace the routing leg with the selected Booking Confirmation leg details for the same Load Port/Discharge?");
				var dialogResult = Globals.Message.ShowOrDefault(dialogContext, confirmation);
				return dialogResult == ZDialogResult.Yes;
			});

			if (!matched)
			{
				Globals.Message.ShowInformation(NoMatchingLegMessage, NoMatchingLegCaption);
			}
		}

