				return;
			}

			var selectedActualEvent = ActualEventsGrid.SelectedElements[0] as ActualEvent;
			var matched = provider.MatchAndUpdateRoutingLeg(selectedActualEvent, () =>
			{
				var caption = ResString.GetMultilingualString("a9a58708-44ee-4314-ae75-3151d63d86c6", "Update Routing Leg - Actual Events");
				var dialogContext = new DialogDefaultContext(new ZGuid("3ee1026d-d3cb-4425-b5c7-0237be8c4ffa"),
					caption,
					ZMessageBoxButtons.YesNo,
					ZMessageBoxIcon.Question,
					null,
					showCheckboxOnly: true);

				var confirmation = ResString.GetMultilingualString("ae162302-bf6b-488e-81ae-dea6cf606f43", "Are you sure you want to update/replace the routing leg with the selected Actual Event leg details for the same Load Port/Discharge?");
				var dialogResult = Globals.Message.ShowOrDefault(dialogContext, confirmation);
				return dialogResult == ZDialogResult.Yes;
			});

			if (!matched)
			{
				Globals.Message.ShowInformation(NoMatchingLegMessage, NoMatchingLegCaption);
			}
		}

		string NoMatchingLegMessage => ResString.GetMultilingualString("aafbe221-b784-4734-8053-cce4da2bbc50", "There is no matching planned leg for the selected event (based on Load Port/Discharge). Please review the selected event and manually update any planned routing leg(s) if required.");
		string NoMatchingLegCaption => ResString.GetMultilingualString("6d66bb11-56dd-4de3-b039-361d577e8603", "Update Routing Leg");

		#endregion
	}
}
